//! The LETTER schema, beside the tests rather than in one: the inbox's shape
//! (`inbox.rs`), whose text is given SEALED PARTS for the husk laws (SPEC
//! §3, laws 71 to 75). A letter's body is a tuple of parts. A part is
//! `Clear(text)`, which every holder reads, or `Boxed(key, box)`, which only
//! a holder of the key `key` opens. A husk drops each `Boxed(key, box)` to
//! `Dropped(key)`, which no key opens. The box holds generated bytes and no
//! cipher: the laws read only which key a part was sealed under.

use prodrome::event::Actor;
use prodrome::fold::{Discrete, Frontier, Product, Register, RegisterType};
use prodrome::literal::{Call, Datetime, ProdromeError, Signature, Table, Value, Vocabulary};
use prodrome::payload::{datetime_field, string_field, tuple_field};
use prodrome::registers::Stamp;
use prodrome::schema::Schema;
use prodrome::store::{HuskObject, Husking, Other};

/// A letter's name: any text.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Id(pub String);

/// One part of a letter's body.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Part {
    /// Text that every holder reads.
    Clear(String),
    /// Text sealed under the key `key`: only a holder of that key opens it.
    Boxed { key: String, sealed: String },
    /// A sealed part whose box was dropped: no key opens it.
    Dropped { key: String },
}

impl Part {
    /// The part as a holder that keeps the keys `kept` reads it: a box it
    /// cannot open reads as the name of its key.
    pub fn read_by(&self, kept: &[&str]) -> Part {
        match self {
            Part::Boxed { key, .. } if !kept.contains(&key.as_str()) => {
                Part::Dropped { key: key.clone() }
            }
            Part::Clear(_) | Part::Boxed { .. } | Part::Dropped { .. } => self.clone(),
        }
    }

    fn to_value(&self) -> Value {
        match self {
            Part::Clear(text) => Value::call("Clear", vec![field("text", Value::str(text))]),
            Part::Boxed { key, sealed } => Value::call(
                "Boxed",
                vec![
                    field("key", Value::str(key)),
                    field("box", Value::str(sealed)),
                ],
            ),
            Part::Dropped { key } => Value::call("Dropped", vec![field("key", Value::str(key))]),
        }
    }

    /// Every form of a part; each vocabulary admits only its own.
    fn from_value(value: &Value) -> Result<Part, ProdromeError> {
        let call: &Call = prodrome::literal::codec::call(value)?;
        match call.name.as_str() {
            "Clear" => Ok(Part::Clear(string_field(call, "text")?)),
            "Boxed" => Ok(Part::Boxed {
                key: string_field(call, "key")?,
                sealed: string_field(call, "box")?,
            }),
            "Dropped" => Ok(Part::Dropped {
                key: string_field(call, "key")?,
            }),
            other => Err(prodrome::literal::codec::no_arm("Part", other)),
        }
    }
}

/// What an event says beside its letter, instant and actor.
#[derive(Debug, Clone, PartialEq)]
pub enum Says {
    /// The letter's body, in parts.
    Wrote(Vec<Part>),
    /// The letter's title, in the clear.
    Titled(String),
}

#[derive(Debug, Clone, PartialEq)]
pub struct Letter {
    pub letter: Id,
    pub at: Datetime,
    pub actor: Actor,
    pub says: Says,
}

impl Letter {
    /// The event as a holder that keeps the keys `kept` reads it.
    pub fn read_by(&self, kept: &[&str]) -> Letter {
        let says = match &self.says {
            Says::Wrote(parts) => {
                Says::Wrote(parts.iter().map(|part| part.read_by(kept)).collect())
            }
            Says::Titled(title) => Says::Titled(title.clone()),
        };
        Letter {
            says,
            ..self.clone()
        }
    }

    /// Does a part of it still hold a box?
    pub fn boxed(&self) -> bool {
        match &self.says {
            Says::Wrote(parts) => parts.iter().any(|part| matches!(part, Part::Boxed { .. })),
            Says::Titled(_) => false,
        }
    }
}

/// The events' constructors and the whole's parts: what a store reads.
const SIGNATURES: &[(&str, &[&str])] = &[
    ("Wrote", &["letter", "at", "actor", "body"]),
    ("Titled", &["letter", "at", "actor", "title"]),
    ("Clear", &["text"]),
    ("Boxed", &["key", "box"]),
];

/// The events' constructors and a husk's parts: no `Boxed`.
const HUSK_SIGNATURES: &[(&str, &[&str])] = &[
    ("Wrote", &["letter", "at", "actor", "body"]),
    ("Titled", &["letter", "at", "actor", "title"]),
    ("Clear", &["text"]),
    ("Dropped", &["key"]),
];

#[derive(Debug, Clone, Default)]
pub struct LetterVocabulary;

impl Vocabulary for LetterVocabulary {
    fn signature(&self, name: &str) -> Option<Signature<'_>> {
        Table(SIGNATURES).find(name)
    }
}

#[derive(Debug, Clone, Default)]
pub struct HuskVocabulary;

impl Vocabulary for HuskVocabulary {
    fn signature(&self, name: &str) -> Option<Signature<'_>> {
        Table(HUSK_SIGNATURES).find(name)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Field {
    Body,
    Title,
}

pub struct BodyRegister;
pub struct TitleRegister;

/// The body register reads which keys sealed each part and the clear text,
/// so a whole and its husk write one value.
impl RegisterType<Letter> for BodyRegister {
    type Value<'e> = Discrete<Vec<Part>>;
    fn value(event: &Letter) -> Option<Discrete<Vec<Part>>> {
        match &event.says {
            Says::Wrote(parts) => Some(Discrete(
                parts.iter().map(|part| part.read_by(&[])).collect(),
            )),
            Says::Titled(_) => None,
        }
    }
}

impl RegisterType<Letter> for TitleRegister {
    type Value<'e> = Discrete<&'e str>;
    fn value(event: &Letter) -> Option<Discrete<&str>> {
        match &event.says {
            Says::Titled(title) => Some(Discrete(title.as_str())),
            Says::Wrote(_) => None,
        }
    }
}

/// A letter's registers: a product of two frontiers.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Registers<'a> {
    body: Frontier<'a, Letter>,
    title: Frontier<'a, Letter>,
}

impl<'a> Product<'a> for Registers<'a> {
    type Schema = Letter;

    fn registers(&self) -> Vec<Field> {
        vec![Field::Body, Field::Title]
    }

    fn frontier(&self, field: Field) -> &Frontier<'a, Letter> {
        match field {
            Field::Body => &self.body,
            Field::Title => &self.title,
        }
    }

    fn join_to(&mut self, field: Field, stamp: &'a Stamp<Letter>) {
        match field {
            Field::Body => self.body.join(stamp),
            Field::Title => self.title.join(stamp),
        }
    }

    fn reading(&self, field: Field) -> Vec<&'a Stamp<Letter>> {
        match field {
            Field::Body => self.body.reading::<BodyRegister>(),
            Field::Title => self.title.reading::<TitleRegister>(),
        }
    }

    fn grows(&self, _: &Letter) -> Result<(), ProdromeError> {
        Ok(())
    }

    fn climbed(&self, _: &Self) -> Result<(), ProdromeError> {
        Ok(())
    }

    fn climbing(&self) -> Vec<Field> {
        Vec::new()
    }
}

fn field(name: &str, value: Value) -> (String, Value) {
    (name.to_owned(), value)
}

/// The letter `value` prints, each part read by `part`.
fn letter(
    value: &Value,
    part: impl Fn(&Value) -> Result<Part, ProdromeError>,
) -> Result<Letter, ProdromeError> {
    let call: &Call = prodrome::literal::codec::call(value)?;
    let says = match call.name.as_str() {
        "Wrote" => Says::Wrote(
            tuple_field(call, "body")?
                .iter()
                .map(part)
                .collect::<Result<_, _>>()?,
        ),
        "Titled" => Says::Titled(string_field(call, "title")?),
        other => return Err(prodrome::literal::codec::no_arm("Letter", other)),
    };
    Ok(Letter {
        letter: Id(string_field(call, "letter")?),
        at: datetime_field(call, "at")?,
        actor: Actor::new(string_field(call, "actor")?)?,
        says,
    })
}

impl Schema for Letter {
    type Vocabulary = LetterVocabulary;
    type Key = Id;
    type Register = Field;
    type Registers<'a> = Registers<'a>;

    fn registers(_: &LetterVocabulary) -> Vec<Field> {
        vec![Field::Body, Field::Title]
    }

    fn to_value(&self) -> Value {
        let (name, last) = match &self.says {
            Says::Wrote(parts) => (
                "Wrote",
                field(
                    "body",
                    Value::Tuple(parts.iter().map(Part::to_value).collect()),
                ),
            ),
            Says::Titled(title) => ("Titled", field("title", Value::str(title.as_str()))),
        };
        Value::call(
            name,
            vec![
                field("letter", Value::str(self.letter.0.as_str())),
                field("at", Value::Datetime(self.at)),
                field("actor", Value::str(self.actor.as_str())),
                last,
            ],
        )
    }

    /// A whole: its vocabulary has no `Dropped`, so a husk's print never
    /// parses as a whole.
    fn from_value(_: &LetterVocabulary, value: &Value) -> Result<Letter, ProdromeError> {
        letter(value, Part::from_value)
    }

    fn key(&self) -> &Id {
        &self.letter
    }

    fn at(&self) -> Datetime {
        self.at
    }

    fn actor(&self) -> &Actor {
        &self.actor
    }

    fn writes(&self) -> impl Iterator<Item = Field> {
        std::iter::once(match self.says {
            Says::Wrote(_) => Field::Body,
            Says::Titled(_) => Field::Title,
        })
    }

    fn husk(print: &Other<'_>) -> Option<HuskObject<Self>> {
        HuskObject::of_other(print).ok()
    }
}

impl Husking for Letter {
    type Seal = String;
    type Husks = HuskVocabulary;

    fn drop_sealed(&self) -> Option<Letter> {
        self.boxed().then(|| self.read_by(&[]))
    }

    fn read_dropped(value: &Value) -> Result<Letter, ProdromeError> {
        let husk = letter(value, |part| match Part::from_value(part)? {
            Part::Boxed { key, .. } => Err(ProdromeError::invalid(format!(
                "a husk holds no sealed part, and this one is sealed under {key}"
            ))),
            read @ (Part::Clear(_) | Part::Dropped { .. }) => Ok(read),
        })?;
        if husk.sealed_under().next().is_none() {
            return Err(ProdromeError::invalid(
                "a husk holds a dropped part, and this holds none",
            ));
        }
        Ok(husk)
    }

    fn sealed_under(&self) -> impl Iterator<Item = &String> {
        let parts: &[Part] = match &self.says {
            Says::Wrote(parts) => parts,
            Says::Titled(_) => &[],
        };
        parts.iter().filter_map(|part| match part {
            Part::Boxed { key, .. } | Part::Dropped { key } => Some(key),
            Part::Clear(_) => None,
        })
    }
}

/// The stored names of the letter schema. A changed name of a constructor or
/// a field, or a changed order of the fields, fails this test.
#[test]
fn the_letter_schema_pins_its_stored_names() {
    prodrome::literal::codec::assert_pinned(
        SIGNATURES,
        "
        Wrote(letter, at, actor, body)
        Titled(letter, at, actor, title)
        Clear(text)
        Boxed(key, box)
        ",
    );
    prodrome::literal::codec::assert_pinned(
        HUSK_SIGNATURES,
        "
        Wrote(letter, at, actor, body)
        Titled(letter, at, actor, title)
        Clear(text)
        Dropped(key)
        ",
    );
}
